test/integration/produtos/ordem.test.js.source:
const chai = require('chai')
const { faker } = require('@faker-js/faker')

const rotaProdutos = '/produtos'
const utils = require('../utils')

describe(rotaProdutos + ' ORDEM DA LISTA', () => {
  let authorization
  beforeEach(async () => {
    const { email, password } = await utils.cadastrarUsuario({ administrador: 'true' })
    authorization = (await utils.login(email, password)).authorization
  })

  it('Produto cadastrado por último vem primeiro', async () => {
    const descricao = faker.string.alphanumeric(24)
    const primeiro = await utils.cadastrarProduto({ descricao, authorization })
    const segundo = await utils.cadastrarProduto({ descricao, authorization })

    const { body } = await request.get(rotaProdutos).query({ descricao }).expect(200)

    chai.assert.deepEqual(body, { quantidade: 2, produtos: [segundo, primeiro] })
  })

  it('Produto alterado volta para o topo', async () => {
    const descricao = faker.string.alphanumeric(24)
    const primeiro = await utils.cadastrarProduto({ descricao, authorization })
    const segundo = await utils.cadastrarProduto({ descricao, authorization })
    const { _id, ...dados } = primeiro
    const alterado = { ...dados, preco: primeiro.preco + 1 }

    await request.put(`${rotaProdutos}/${_id}`).set('authorization', authorization).send(alterado).expect(200)
    const { body } = await request.get(rotaProdutos).query({ descricao }).expect(200)

    chai.assert.deepEqual(body, { quantidade: 2, produtos: [{ ...alterado, _id }, segundo] })
  })

  it('Produto não muda de posição quando um carrinho baixa ou repõe o estoque', async () => {
    const descricao = faker.string.alphanumeric(24)
    const primeiro = await utils.cadastrarProduto({ descricao, quantidade: 10, authorization })
    const segundo = await utils.cadastrarProduto({ descricao, authorization })

    await utils.cadastrarCarrinho({ idProduto: primeiro._id, quantidade: 1, authorization })
    const { body: depoisDoCarrinho } = await request.get(rotaProdutos).query({ descricao }).expect(200)
    await request.del('/carrinhos/cancelar-compra').set('authorization', authorization).expect(200)
    const { body: depoisDoCancelamento } = await request.get(rotaProdutos).query({ descricao }).expect(200)

    chai.assert.deepEqual(depoisDoCarrinho, { quantidade: 2, produtos: [segundo, { ...primeiro, quantidade: 9 }] })
    chai.assert.deepEqual(depoisDoCancelamento, { quantidade: 2, produtos: [segundo, primeiro] })
  })

  it('Produto cadastrado vem antes dos produtos da semente - @skipE2E', async () => {
    const produto = await utils.cadastrarProduto({ authorization })

    const { body } = await request.get(rotaProdutos).expect(200)
    const ids = body.produtos.map(({ _id }) => _id)

    chai.assert.isBelow(ids.indexOf(produto._id), ids.indexOf('BeeJh5lz3k6kSIzA'))
    chai.assert.isBelow(ids.indexOf(produto._id), ids.indexOf('K6leHdftCeOJj8BJ'))
  })

  it('Lista e busca por id não mostram o campo interno de ordenação', async () => {
    const produto = await utils.cadastrarProduto({ authorization })

    const { body: lista } = await request.get(rotaProdutos).query({ _id: produto._id }).expect(200)
    const { body: porId } = await request.get(`${rotaProdutos}/${produto._id}`).expect(200)

    chai.assert.deepEqual(lista.produtos, [produto])
    chai.assert.deepEqual(porId, produto)
    chai.assert.notProperty(porId, 'alteradoEm')
  })
})

test/integration/produtos/post.test.js.source:
const chai = require('chai')

const rotaProdutos = '/produtos'
const utils = require('../utils')

describe(rotaProdutos + ' POST', () => {
  let authorizationAdministrador
  beforeEach(async () => {
    const { email, password } = await utils.cadastrarUsuario({ administrador: 'true' })
    const { authorization } = await utils.login(email, password)
    authorizationAdministrador = authorization
  })

  it('Cadastro com sucesso', async () => {
    const { body } = await request.post(rotaProdutos).send(utils.dadosProduto()).set('authorization', authorizationAdministrador).expect(201)

    chai.assert.deepEqual(body, { message: 'Cadastro realizado com sucesso', _id: body._id })
  })

  it('Cadastro sem imagem do produto com sucesso', async () => {
    const produto = utils.dadosProduto()
    delete produto.imagem

    const { body } = await request.post(rotaProdutos).send(produto).set('authorization', authorizationAdministrador).expect(201)

    chai.assert.deepEqual(body, { message: 'Cadastro realizado com sucesso', _id: body._id })
  })

  it('Nome já utilizado', async () => {
    const produto = utils.dadosProduto()

    await request
      .post(rotaProdutos)
      .send(produto)
      .set('authorization', authorizationAdministrador)
      .expect(201)
    const { body } = await request
      .post(rotaProdutos)
      .send(produto)
      .set('authorization', authorizationAdministrador)
      .expect(400)

    chai.assert.deepEqual(body, { message: 'Já existe produto com esse nome' })
  })

  it('Token inválido', async () => {
    const { body } = await request.post(rotaProdutos).send(utils.dadosProduto()).set('authorization', 'a').expect(401)

    chai.assert.deepEqual(body, {
      message: 'Token de acesso ausente, inválido, expirado ou usuário do token não existe mais'
    })
  })

  it('Rota para administradores', async () => {
    const { email, password } = await utils.cadastrarUsuario({ administrador: 'false' })
    const { authorization } = await utils.login(email, password)
    const { body } = await request.post(rotaProdutos).send(utils.dadosProduto()).set('authorization', authorization).expect(403)

    chai.assert.deepEqual(body, {
      message: 'Rota exclusiva para administradores'
    })
  })

  it('Bad request - Campos de preenchimento obrigatório', async () => {
    const { body } = await request
      .post(rotaProdutos)
      .send({ inexistente: 'teste' })
      .set('authorization', authorizationAdministrador)
      .expect(400)

    chai.assert.deepEqual(body, {
      nome: 'nome é obrigatório',
      preco: 'preco é obrigatório',
      descricao: 'descricao é obrigatório',
      quantidade: 'quantidade é obrigatório',
      inexistente: 'inexistente não é permitido'
    })
  })

  it('Bad request - quantidade deve ser maior ou igual a 0 - Não deve permitir valor negativo', async () => {
    const { body } = await request
      .post(rotaProdutos)
      .send({ quantidade: -1 })
      .set('authorization', authorizationAdministrador)
      .expect(400)

    chai.assert.deepEqual(body, {
      nome: 'nome é obrigatório',
      preco: 'preco é obrigatório',
      descricao: 'descricao é obrigatório',
      quantidade: 'quantidade deve ser maior ou igual a 0'
    })
  })

  it('Bad request - quantidade deve ser maior ou igual a 0 - Deve permitir 0', async () => {
    const { body } = await request
      .post(rotaProdutos)
      .send({ quantidade: 0 })
      .set('authorization', authorizationAdministrador)
      .expect(400)

    chai.assert.deepEqual(body, {
      nome: 'nome é obrigatório',
      preco: 'preco é obrigatório',
      descricao: 'descricao é obrigatório'
    })
  })

  it('Bad request - imagem deve ser uma string', async () => {
    let produto = utils.dadosProduto()
    produto = {
      ...produto,
      imagem: 1
    }

    const numberRequest = await request
      .post(rotaProdutos)
      .send(produto)
      .set('authorization', authorizationAdministrador)
      .expect(400)

    chai.assert.deepEqual(numberRequest.body, {
      imagem: 'imagem deve ser uma string'
    })

    produto = {
      ...produto,
      imagem: null
    }

    const nullRequest = await request
      .post(rotaProdutos)
      .send(produto)
      .set('authorization', authorizationAdministrador)
      .expect(400)

    chai.assert.deepEqual(nullRequest.body, {
      imagem: 'imagem deve ser uma string'
    })
  })

  // O serviço tira os espaços em volta de nome e imagem antes de gravar; só espaços viraria "".
  describe('Texto só com espaços', () => {
    it('Bad request - nome só com espaços não é aceito', async () => {
      const { body } = await request
        .post(rotaProdutos)
        .send({ ...utils.dadosProduto(), nome: '   ' })
        .set('authorization', authorizationAdministrador)
        .expect(400)

      chai.assert.deepEqual(body, {
        nome: 'nome não pode ficar em branco'
      })
    })

    it('Bad request - imagem só com espaços não é aceita', async () => {
      const { body } = await request
        .post(rotaProdutos)
        .send({ ...utils.dadosProduto(), imagem: '   ' })
        .set('authorization', authorizationAdministrador)
        .expect(400)

      chai.assert.deepEqual(body, {
        imagem: 'imagem não pode ficar em branco'
      })
    })

    it('Nome e imagem com espaços em volta do texto são aceitos e gravados sem esses espaços', async () => {
      const produto = utils.dadosProduto()

      const { body } = await request
        .post(rotaProdutos)
        .send({ ...produto, nome: `  ${produto.nome}  `, imagem: `  ${produto.imagem}  ` })
        .set('authorization', authorizationAdministrador)
        .expect(201)

      const { body: produtoGravado } = await request.get(`${rotaProdutos}/${body._id}`).expect(200)
      chai.assert.deepEqual(produtoGravado, { ...produto, _id: body._id })
    })
  })

  // Formulário HTML envia todo valor como texto. O Joi aceita o texto numérico e o serviço grava o número.
  describe('Número enviado como string', () => {
    it('preco e quantidade como string numérica são aceitos e gravados como número', async () => {
      const produto = utils.dadosProduto()

      const { body } = await request
        .post(rotaProdutos)
        .send({ ...produto, preco: '470', quantidade: '5' })
        .set('authorization', authorizationAdministrador)
        .expect(201)

      const { body: produtoGravado } = await request.get(`${rotaProdutos}/${body._id}`).expect(200)
      chai.assert.deepEqual(produtoGravado, { ...produto, preco: 470, quantidade: 5, _id: body._id })
    })

    it('preco como string em notação científica é aceito e gravado pelo valor convertido', async () => {
      const { body } = await request
        .post(rotaProdutos)
        .send({ ...utils.dadosProduto(), preco: '4e2' })
        .set('authorization', authorizationAdministrador)
        .expect(201)

      const { body: produtoGravado } = await request.get(`${rotaProdutos}/${body._id}`).expect(200)
      chai.assert.strictEqual(produtoGravado.preco, 400)
    })

    it('corpo em application/x-www-form-urlencoded é aceito e gravado com números', async () => {
      const produto = utils.dadosProduto()

      const { body } = await request
        .post(rotaProdutos)
        .type('form')
        .send(produto)
        .set('authorization', authorizationAdministrador)
        .expect(201)

      const { body: produtoGravado } = await request.get(`${rotaProdutos}/${body._id}`).expect(200)
      chai.assert.deepEqual(produtoGravado, { ...produto, _id: body._id })
    })

    it('quantidade como string "-0" é aceita e gravada como 0', async () => {
      const { body } = await request
        .post(rotaProdutos)
        .send({ ...utils.dadosProduto(), quantidade: '-0' })
        .set('authorization', authorizationAdministrador)
        .expect(201)

      const { body: produtoGravado } = await request.get(`${rotaProdutos}/${body._id}`).expect(200)
      chai.assert.strictEqual(produtoGravado.quantidade, 0)
    })

    it('Bad request - preco e quantidade como string não numérica não são aceitos', async () => {
      const { body } = await request
        .post(rotaProdutos)
        .send({ ...utils.dadosProduto(), preco: 'abc', quantidade: 'abc' })
        .set('authorization', authorizationAdministrador)
        .expect(400)

      chai.assert.deepEqual(body, {
        preco: 'preco deve ser um número',
        quantidade: 'quantidade deve ser um número'
      })
    })

    it('Bad request - preco e quantidade como string decimal não são aceitos', async () => {
      const { body } = await request
        .post(rotaProdutos)
        .send({ ...utils.dadosProduto(), preco: '4.5', quantidade: '1.5' })
        .set('authorization', authorizationAdministrador)
        .expect(400)

      chai.assert.deepEqual(body, {
        preco: 'preco deve ser um inteiro',
        quantidade: 'quantidade deve ser um inteiro'
      })
    })

    it('Bad request - preco e quantidade como string negativa não são aceitos', async () => {
      const { body } = await request
        .post(rotaProdutos)
        .send({ ...utils.dadosProduto(), preco: '-3', quantidade: '-1' })
        .set('authorization', authorizationAdministrador)
        .expect(400)

      chai.assert.deepEqual(body, {
        preco: 'preco deve ser um número positivo',
        quantidade: 'quantidade deve ser maior ou igual a 0'
      })
    })
  })

  describe('Number.MAX_SAFE_INTEGER', () => {
    it('Deve retornar erro 400 ao enviar número inteiro maior que Number.MAX_SAFE_INTEGER', async () => {
      let produto = utils.dadosProduto()
      produto = {
        ...produto,
        preco: Number.MAX_SAFE_INTEGER + 1
      }

      const { body } = await request
        .post('/produtos')
        .send(produto)
        .set('authorization', authorizationAdministrador)
        .expect(400)

      chai.assert.deepEqual(body, {
        preco: `preco não pode ser maior que ${Number.MAX_SAFE_INTEGER}`
      })
    })

    it('Deve cadastrar produto com sucesso ao enviar preco igual a Number.MAX_SAFE_INTEGER', async () => {
      let produto = utils.dadosProduto()
      produto = {
        ...produto,
        preco: Number.MAX_SAFE_INTEGER
      }

      const { body } = await request
        .post('/produtos')
        .send(produto)
        .set('authorization', authorizationAdministrador)
        .expect(201)

      chai.assert.deepEqual(body, {
        message: 'Cadastro realizado com sucesso',
        _id: body._id
      })
    })
  })
})

