    const { _id: idProdutoB } = await utils.cadastrarProduto({ authorization, quantidade: 10 })

    const { body } = await request.post(rotaCarrinhos).set('authorization', authorization).send({
      produtos: [
        { idProduto: idProdutoA, quantidade: 1 },
        { idProduto: idProdutoB, quantidade: 1 },
        { idProduto: idProdutoA, quantidade: 1 }
      ]
    }).expect(400)

    chai.assert.deepEqual(body, {
      message: 'Não é permitido possuir produto duplicado',
      idProdutosDuplicados: [
        idProdutoA
      ]
    })
  })

  it('Não é permitido possuir produto duplicado quando os repetidos são vizinhos e há outro produto', async () => {
    const authorization = authorizationAdministrador
    const { _id: idProdutoA } = await utils.cadastrarProduto({ authorization, quantidade: 10 })
    const { _id: idProdutoB } = await utils.cadastrarProduto({ authorization, quantidade: 10 })

    const { body } = await request.post(rotaCarrinhos).set('authorization', authorization).send({
      produtos: [
        { idProduto: idProdutoA, quantidade: 1 },
        { idProduto: idProdutoA, quantidade: 1 },
        { idProduto: idProdutoB, quantidade: 1 }
      ]
    }).expect(400)

    chai.assert.deepEqual(body, {
      message: 'Não é permitido possuir produto duplicado',
      idProdutosDuplicados: [
        idProdutoA
      ]
    })
  })

  it('Produto duplicado não vizinho não altera o estoque de nenhum produto', async () => {
    const authorization = authorizationAdministrador
    const { _id: idProdutoA } = await utils.cadastrarProduto({ authorization, quantidade: 6 })
    const { _id: idProdutoB } = await utils.cadastrarProduto({ authorization, quantidade: 10 })

    const { body: produtoAAntes } = await request.get(`/produtos/${idProdutoA}`).expect(200)
    const { body: produtoBAntes } = await request.get(`/produtos/${idProdutoB}`).expect(200)

    await request.post(rotaCarrinhos).set('authorization', authorization).send({
      produtos: [
        { idProduto: idProdutoA, quantidade: 5 },
        { idProduto: idProdutoB, quantidade: 1 },
        { idProduto: idProdutoA, quantidade: 5 }
      ]
    }).expect(400)

    const { body: produtoADepois } = await request.get(`/produtos/${idProdutoA}`).expect(200)
    const { body: produtoBDepois } = await request.get(`/produtos/${idProdutoB}`).expect(200)

    chai.assert.strictEqual(produtoAAntes.quantidade, 6)
    chai.assert.strictEqual(produtoBAntes.quantidade, 10)
    chai.assert.strictEqual(produtoADepois.quantidade, 6)
    chai.assert.strictEqual(produtoBDepois.quantidade, 10)
  })

  it('Produto duplicado não vizinho não cria carrinho para o usuário', async () => {
    const authorization = authorizationAdministrador
    const { _id: idProdutoA } = await utils.cadastrarProduto({ authorization, quantidade: 10 })
    const { _id: idProdutoB } = await utils.cadastrarProduto({ authorization, quantidade: 10 })

    await request.post(rotaCarrinhos).set('authorization', authorization).send({
      produtos: [
        { idProduto: idProdutoA, quantidade: 1 },
        { idProduto: idProdutoB, quantidade: 1 },
        { idProduto: idProdutoA, quantidade: 1 }
      ]
    }).expect(400)

    const { body } = await request.get(rotaCarrinhos).query({ idUsuario: idUsuarioAdministrador }).expect(200)

    chai.assert.deepEqual(body, { quantidade: 0, carrinhos: [] })
  })

  it('Não é permitido ter mais de 1 carrinho', async () => {
    const authorization = authorizationAdministrador
    const quantidade = utils.quantidadeAleatoria()
    const { _id: idProduto } = await utils.cadastrarProduto({ authorization, quantidade })

    await request.post(rotaCarrinhos).set('authorization', authorization).send({
      produtos: [{
        idProduto,
        quantidade
      }]
    }).expect(201)
    const { body } = await request.post(rotaCarrinhos).set('authorization', authorization).send({
      produtos: [{
        idProduto,
        quantidade
      }]
    }).expect(400)

    chai.assert.deepEqual(body, { message: 'Não é permitido ter mais de 1 carrinho' })
  })

  it('Produto não encontrado', async () => {
    const authorization = authorizationAdministrador
    const produtoInexistente = {
      idProduto: 'asdasd',
      quantidade: 2
    }
    const { _id: idProduto } = await utils.cadastrarProduto({ authorization })
    const { body } = await request.post(rotaCarrinhos).set('authorization', authorization).send({
      produtos: [{
        idProduto,
        quantidade: 1
      }, {
        idProduto: produtoInexistente.idProduto,
        quantidade: produtoInexistente.quantidade
      }]
    }).expect(400)

    chai.assert.deepEqual(body, {
      message: 'Produto não encontrado',
      item: {
        index: 1,
        idProduto: produtoInexistente.idProduto,
        quantidade: produtoInexistente.quantidade
      }
    })
  })

  // Fora do E2E: não deixa produto e carrinho com valor extremo nos ambientes compartilhados.
  describe('Totais acima de Number.MAX_SAFE_INTEGER - @skipE2E', () => {
    it('precoTotal acima do limite não cadastra o carrinho nem baixa o estoque', async () => {
      const authorization = authorizationAdministrador
      const { _id: idProduto } = await utils.cadastrarProduto({ authorization, preco: Number.MAX_SAFE_INTEGER, quantidade: 2 })

      const { body } = await request.post(rotaCarrinhos).set('authorization', authorization).send({
        produtos: [{ idProduto, quantidade: 2 }]
      }).expect(400)

      chai.assert.deepEqual(body, { message: 'precoTotal ou quantidadeTotal do carrinho não pode passar de 9007199254740991' })
      const { body: bodyProduto } = await request.get('/produtos').query({ _id: idProduto }).expect(200)
      chai.assert.equal(bodyProduto.produtos[0].quantidade, 2)
      const { body: bodyCarrinhos } = await request.get(rotaCarrinhos).query({ idUsuario: idUsuarioAdministrador }).expect(200)
      chai.assert.deepEqual(bodyCarrinhos, { quantidade: 0, carrinhos: [] })
    })

    it('precoTotal no limite cadastra o carrinho', async () => {
      const authorization = authorizationAdministrador
      const { _id: idProduto } = await utils.cadastrarProduto({ authorization, preco: Number.MAX_SAFE_INTEGER, quantidade: 1 })

      const { body } = await request.post(rotaCarrinhos).set('authorization', authorization).send({
        produtos: [{ idProduto, quantidade: 1 }]
      }).expect(201)

      const { body: carrinho } = await request.get(`${rotaCarrinhos}/${body._id}`).expect(200)
      chai.assert.equal(carrinho.precoTotal, Number.MAX_SAFE_INTEGER)
    })

    it('Estoque insuficiente responde antes do limite dos totais', async () => {
      const authorization = authorizationAdministrador
      const { _id: idProduto } = await utils.cadastrarProduto({ authorization, preco: Number.MAX_SAFE_INTEGER, quantidade: 1 })

      const { body } = await request.post(rotaCarrinhos).set('authorization', authorization).send({
        produtos: [{ idProduto, quantidade: 2 }]
      }).expect(400)

      chai.assert.equal(body.message, 'Produto não possui quantidade suficiente')
    })

    it('Produto inexistente responde antes do limite dos totais', async () => {
      const authorization = authorizationAdministrador
      const { _id: idProduto } = await utils.cadastrarProduto({ authorization, preco: Number.MAX_SAFE_INTEGER, quantidade: 2 })

      const { body } = await request.post(rotaCarrinhos).set('authorization', authorization).send({
        produtos: [{ idProduto, quantidade: 2 }, { idProduto: 'inexistente', quantidade: 1 }]
      }).expect(400)

      chai.assert.equal(body.message, 'Produto não encontrado')
    })
  })

  it('Produto sem quantidade suficiente', async () => {
    const authorization = authorizationAdministrador
    const quantidade = utils.quantidadeAleatoria()
    const { _id: idProduto } = await utils.cadastrarProduto({ authorization, quantidade })
    const { body } = await request.post(rotaCarrinhos).set('authorization', authorization).send({
      produtos: [{
        idProduto,
        quantidade: quantidade + 1
      }]
    }).expect(400)

    chai.assert.deepEqual(body, {
      message: 'Produto não possui quantidade suficiente',
      item: {
        index: 0,
        idProduto,
        quantidade: quantidade + 1,
        quantidadeEstoque: quantidade
      }
    })
  })

  it('Token inválido', async () => {
    const { body } = await request.post(rotaCarrinhos).set('authorization', 'asdasd').send({
      produtos: [{
        idProduto: 'a',
        quantidade: 1
      }]
    }).expect(401)

    chai.assert.deepEqual(body, {
      message: 'Token de acesso ausente, inválido, expirado ou usuário do token não existe mais'
    })
  })

  it('Bad request - Chave inválida', async () => {
    const { body } = await request
      .post(rotaCarrinhos)
      .send({ inexistente: 'teste' })
      .set('authorization', authorizationAdministrador)
      .expect(400)

    chai.assert.deepEqual(body, {

      produtos: 'produtos é obrigatório',
      inexistente: 'inexistente não é permitido'
    })
  })

  it('Bad request - Array produtos em branco', async () => {
    const { body } = await request
      .post(rotaCarrinhos)
      .send({ produtos: [{}] })
      .set('authorization', authorizationAdministrador)
      .expect(400)

    chai.assert.deepEqual(body, {
      'produtos[0].idProduto': 'produtos[0].idProduto é obrigatório',
      'produtos[0].quantidade': 'produtos[0].quantidade é obrigatório'
    })
  })

  it('Bad request - produtos deve ter pelo menos 1 item', async () => {
    const { body } = await request
      .post(rotaCarrinhos)
      .send({ produtos: [] })
      .set('authorization', authorizationAdministrador)
      .expect(400)

    chai.assert.deepEqual(body, {
      produtos: 'produtos deve ter pelo menos 1 item'
    })
  })

  it('Bad request - produtos deve ser array', async () => {
    const { body } = await request
      .post(rotaCarrinhos)
      .send({ produtos: {} })
      .set('authorization', authorizationAdministrador)
      .expect(400)

    chai.assert.deepEqual(body, {
      produtos: 'produtos deve ser um array'
    })
  })

  it('Bad request - idProduto deve ser string e quantidade deve ser número', async () => {
    const { body } = await request
      .post(rotaCarrinhos)
      .send({
        produtos: [{
          idProduto: 0,
          quantidade: 'a'
        }]
      })
      .set('authorization', authorizationAdministrador)
      .expect(400)

    chai.assert.deepEqual(body, {
      'produtos[0].idProduto': 'produtos[0].idProduto deve ser uma string',
      'produtos[0].quantidade': 'produtos[0].quantidade deve ser um número'
    })
  })

  it('quantidade como string numérica é aceita e o carrinho grava números', async () => {
    const authorization = authorizationAdministrador
    const { _id: idProduto } = await utils.cadastrarProduto({ authorization, preco: 470, quantidade: 10 })

    const { body } = await request
      .post(rotaCarrinhos)
      .send({
        produtos: [{
          idProduto,
          quantidade: '2'
        }]
      })
      .set('authorization', authorization)
      .expect(201)

    const { body: bodyCarrinho } = await request.get(`${rotaCarrinhos}/${body._id}`).expect(200)
    const { body: bodyProduto } = await request.get(`/produtos/${idProduto}`).expect(200)

    chai.assert.strictEqual(bodyCarrinho.produtos[0].quantidade, 2)
    chai.assert.strictEqual(bodyCarrinho.quantidadeTotal, 2)
    chai.assert.strictEqual(bodyCarrinho.precoTotal, 940)
    chai.assert.strictEqual(bodyProduto.quantidade, 8)
  })

  it('Bad request - quantidade como string não numérica não é aceita e o estoque não muda', async () => {
    const authorization = authorizationAdministrador
    const { _id: idProduto } = await utils.cadastrarProduto({ authorization, quantidade: 10 })

    const { body } = await request
      .post(rotaCarrinhos)
      .send({
        produtos: [{
          idProduto,
          quantidade: 'abc'
        }]
      })
      .set('authorization', authorization)
      .expect(400)

    chai.assert.deepEqual(body, {
      'produtos[0].quantidade': 'produtos[0].quantidade deve ser um número'
    })

    const { body: bodyProduto } = await request.get(`/produtos/${idProduto}`).expect(200)

    chai.assert.strictEqual(bodyProduto.quantidade, 10)
  })

  it('Bad request - quantidade como string decimal não é aceita', async () => {
    const { body } = await request
      .post(rotaCarrinhos)
      .send({
        produtos: [{
          idProduto: 'basdasd',
          quantidade: '1.5'
        }]
      })
      .set('authorization', authorizationAdministrador)
      .expect(400)

    chai.assert.deepEqual(body, {
      'produtos[0].quantidade': 'produtos[0].quantidade deve ser um inteiro'
    })
  })

  it('Bad request - quantidade deve ser inteiro', async () => {
    const { body } = await request
      .post(rotaCarrinhos)
      .send({
        produtos: [{
          idProduto: 'basdasd',
          quantidade: -1.1
        }]
      })
      .set('authorization', authorizationAdministrador)
      .expect(400)

    chai.assert.deepEqual(body, {
      'produtos[0].quantidade': 'produtos[0].quantidade deve ser um inteiro'
    })
  })

  it('Bad request - quantidade deve ser um número positivo', async () => {
    const { body } = await request
      .post(rotaCarrinhos)
      .send({
        produtos: [{
          idProduto: 'asdasd',
          quantidade: 0
        }]
      })
      .set('authorization', authorizationAdministrador)
      .expect(400)

    chai.assert.deepEqual(body, {
      'produtos[0].quantidade': 'produtos[0].quantidade deve ser um número positivo'
    })
  })

  it('Bad request - deve ser um objeto', async () => {
    const { body } = await request
      .post(rotaCarrinhos)
      .send([null])
      .set('authorization', authorizationAdministrador)
      .expect(400)

    chai.assert.deepEqual(body, {
      value: 'value deve ser um objeto'
    })
  })
})

